(function(){'use strict';
/* "AI Project Scaffolding Database" generator — "jahdb-ai-toolmaking-project-scaffolding-1.0".
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   Type 1: Fact-checked public information.. */
function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;}}
var PREFIX="JAH-TMSCF-";
var DBTITLE="AI Project Scaffolding Database";
var DESC="Everything an AI (or a human) needs to start a new tool or website from zero: project templates, monorepo layouts, starter kits, build configs, and environment setup \u2014 each record a complete, working starting point with real code, real configs, and the reasoning behind every choice.";
var CATS=["project-templates", "monorepo-layouts", "starter-kits", "build-configs", "env-setup"];
var SRC="public";
var SRC_DETAIL="Fact-checked public information; record assembly follows the database standard and is labeled.";
var REQUIRED=["name","how_it_works","key_points","requirements","standards","citations"];
var DATA=[{"t": "Choosing a Project Template Engine", "cat": "project-templates", "d": "A template engine turns a blank folder into a working project in seconds. Cookiecutter (Python, language-agnostic), Yeoman (Node generators), create-* CLIs (create-react-app, create-next-app), and degit (git-repo cloning without history) each fit different cases. The rule is simple: if you scaffold the same shape twice, template it. A good template pins dependency versions, includes CI, linting, tests, and docs from the start, and asks only the questions that change the output (name, license, package manager).", "h": "Pick the engine that matches the ecosystem, author a template directory with placeholder variables, add a post-generation hook that installs dependencies, then generate with one command and verify the output builds and tests green before shipping the template.", "k": ["Template anything scaffolded twice — repetition is the trigger.", "Pin versions inside templates so generated projects are reproducible.", "Ship CI, lint, tests, and a README in every template by default.", "Ask only questions that change output; default everything else."], "r": ["A template engine installed (cookiecutter, yeoman, or degit).", "A known-good reference project to extract the template from.", "A clean directory and one full generate-and-verify cycle."], "s": ["Templates must generate a project that builds and passes tests untouched.", "Generated projects carry the same license headers as the template."], "c": ["Cookiecutter documentation — cookiecutter.readthedocs.io", "Yeoman authoring guide — yeoman.io/authoring"], "sig": "Signature rule: every Signature template embeds a self-check script that fails loudly if the generated project drifts from the template's own CI.", "demo": "# scaffold a node CLI from a git template with degit (no history)\nnpx degit github:user/node-cli-template my-tool\ncd my-tool && npm install && npm test\necho \"scaffolded and verified\""}, {"t": "Monorepo Template with pnpm Workspaces", "cat": "project-templates", "d": "A pnpm-workspaces monorepo template gives one repo, many packages, one install. The template ships pnpm-workspace.yaml listing packages/*, a root package.json with shared scripts (build, test, lint run recursively via pnpm -r), and a shared tsconfig base. AI code generators love monorepos because cross-package refactors happen in one diff. pnpm's content-addressed store keeps installs fast and disk-cheap, and strict peer-dependency handling catches version conflicts early instead of at runtime.", "h": "Create pnpm-workspace.yaml with package globs, add a root package.json whose scripts delegate with pnpm -r, place shared configs at the root, scaffold packages/web and packages/api, then run pnpm install and confirm both packages resolve the shared workspace dependency.", "k": ["One lockfile at the root — never per-package lockfiles.", "Shared tsconfig/eslint bases keep packages consistent.", "pnpm -r runs scripts across every package in dependency order.", "Workspace protocol (workspace:*) links local packages without publishing."], "r": ["pnpm 8+ installed.", "Node 18+.", "A root folder to become the monorepo."], "s": ["pnpm-workspace.yaml must exist before install.", "No nested node_modules committed; .gitignore covers them."], "c": ["pnpm workspaces docs — pnpm.io/workspaces", "Monorepo tools comparison — monorepo.tools"], "sig": "Signature rule: Signature monorepos add a packages/_meta package that documents every package's purpose so an AI navigator never guesses.", "demo": "cat > pnpm-workspace.yaml <<'EOF'\npackages:\n  - 'packages/*'\nEOF\nmkdir -p packages/web packages/api\ncat > package.json <<'EOF'\n{\"name\":\"acme-mono\",\"private\":true,\"scripts\":{\"build\":\"pnpm -r build\"}}\nEOF\npnpm install && echo \"monorepo ready\""}, {"t": "Microservice Template with Docker", "cat": "project-templates", "d": "A microservice template standardizes the boring parts: a Dockerfile with multi-stage builds, a .dockerignore, health-check endpoint, structured logging, graceful shutdown, and environment-based config. Each service gets the same skeleton so AI-generated services are operationally identical — same log format, same /healthz, same signal handling. The template also ships docker-compose.yml wiring the service to its database and a CI job that builds and pushes the image on every merge.", "h": "Author a multi-stage Dockerfile (deps → build → slim runtime), add /healthz and SIGTERM handling to the app skeleton, write docker-compose.yml for local dependencies, then build the image, run the compose stack, and curl the health endpoint to prove the template works end to end.", "k": ["Multi-stage builds keep production images small and secret-free.", "Every service exposes /healthz — orchestrators depend on it.", "Graceful shutdown on SIGTERM prevents dropped requests.", "docker-compose gives a one-command local stack for development."], "r": ["Docker 24+ and docker compose.", "A base image pinned by digest, not just tag.", "Port assignments documented to avoid collisions."], "s": ["Production stage runs as a non-root user.", "No secrets baked into images; injected at runtime."], "c": ["Dockerfile best practices — docs.docker.com/develop/dev-best-practices", "12-Factor App — 12factor.net"], "sig": "Signature rule: Signature service templates fail the build if /healthz is missing — health is structural, not optional.", "demo": "cat > Dockerfile <<'EOF'\nFROM node:20-alpine AS deps\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci --omit=dev\nFROM node:20-alpine\nWORKDIR /app\nCOPY --from=deps /app/node_modules ./node_modules\nCOPY . .\nUSER node\nEXPOSE 3000\nHEALTHCHECK CMD wget -qO- http://localhost:3000/healthz\nCMD [\"node\",\"server.js\"]\nEOF\ndocker build -t svc:template . && echo \"image built\""}, {"t": "CLI Tool Template (Node)", "cat": "project-templates", "d": "A Node CLI template gives you argument parsing, help output, colored errors, config-file support, and update notifications on day one. Use a real parser (commander or yargs) instead of hand-rolling argv handling — edge cases like --no-flag and quoted values are already solved. The template includes a bin entry in package.json, shebang line, tests that spawn the binary and assert exit codes, and a publish workflow. AI-generated CLIs built on this template behave like professional tools immediately.", "h": "Scaffold package.json with a bin field, write the entry file with a shebang and a commander program (version, options, action), add tests that exec the binary and check stdout and exit codes, then npm link locally and run --help to verify.", "k": ["Use commander/yargs — never hand-parse process.argv.", "Tests spawn the real binary and assert exit codes.", "bin + shebang makes the tool installable globally via npm.", "--help and --version are mandatory; users expect them."], "r": ["Node 18+.", "commander or yargs dependency.", "npm link for local testing."], "s": ["Exit code 0 on success, non-zero with a message on stderr for failures.", "No unhandled promise rejections — catch and exit cleanly."], "c": ["commander.js docs — github.com/tj/commander.js", "Node CLI best practices — github.com/lirantal/nodejs-cli-apps-best-practices"], "sig": "Signature rule: Signature CLIs print machine-readable JSON with --json on every command — humans get prose, pipelines get data.", "demo": "cat > cli.js <<'EOF'\n#!/usr/bin/env node\nconst {program}=require('commander');\nprogram.name('greet').version('1.0.0')\n .argument('[name]','who to greet','world')\n .option('--json','machine output')\n .action((name,o)=>{o.json?console.log(JSON.stringify({greeting:'hi '+name})):console.log('hi '+name);});\nprogram.parse();\nEOF\nchmod +x cli.js && ./cli.js --json Ada"}, {"t": "Python Package Template (pyproject)", "cat": "project-templates", "d": "A modern Python package template centers on pyproject.toml: build system, project metadata, optional dependencies, and tool config (ruff, pytest, mypy) in one file — setup.py is legacy. The template lays out src/<pkg>/ layout (so tests import the installed package, not the local folder), includes a tests/ directory, GitHub Actions CI running pytest across Python versions, and a publish job. AI-generated Python tools on this template install cleanly with pip and behave correctly in every environment.", "h": "Write pyproject.toml with build-system, project metadata, and tool sections; create src/<pkg>/__init__.py and tests/test_smoke.py; add CI running pytest on 3.10–3.12; then pip install -e . and run pytest to verify the template end to end.", "k": ["pyproject.toml replaces setup.py/setup.cfg — one metadata file.", "src/ layout prevents importing the wrong copy during tests.", "Declare extras (test, dev) so contributors install one command.", "CI tests a matrix of Python versions, not just yours."], "r": ["Python 3.10+.", "pip and a build backend (hatchling or setuptools).", "pytest for the test suite."], "s": ["Package builds to wheel + sdist without warnings.", "All public functions have docstrings."], "c": ["Python packaging guide — packaging.python.org", "pyproject.toml spec — packaging.python.org/en/latest/specifications/pyproject-toml"], "sig": "Signature rule: Signature Python templates pin a minimum Python and test exactly that floor — supporting old versions is proven, not claimed.", "demo": "cat > pyproject.toml <<'EOF'\n[build-system]\nrequires=[\"hatchling\"]\nbuild-backend=\"hatchling.build\"\n[project]\nname=\"acme-tool\"\nversion=\"0.1.0\"\nrequires-python=\">=3.10\"\n[project.optional-dependencies]\ntest=[\"pytest\"]\nEOF\nmkdir -p src/acme_tool tests\necho 'def hi(n): return \"hi \"+n' > src/acme_tool/__init__.py\npip install -e . -q && python -c \"import acme_tool; print(acme_tool.hi('Ada'))\""}, {"t": "Static Site Template", "cat": "project-templates", "d": "A static site template is the fastest path to a website: an index.html, a styles directory, a script directory, and a build step that can be zero (plain files) or a generator (Eleventy, Astro). The template includes sensible defaults — responsive viewport meta, semantic HTML skeleton, a 404 page, sitemap generation, and deploy config for a static host. AI-generated content sites built on this template are fast, cheap to host, and need no server maintenance.", "h": "Scaffold index.html with semantic landmarks and meta tags, add styles.css and main.js, create 404.html and a sitemap template, configure the static host's publish directory, then serve locally and run a link check before deploying.", "k": ["Semantic HTML skeleton — header/main/footer/nav from the start.", "404 page and sitemap are part of the template, not afterthoughts.", "Zero-build option keeps the simplest sites simplest.", "Lighthouse score checked in CI so performance never regresses."], "r": ["Any static host (or none — plain files work).", "A local server for preview (python -m http.server).", "A link checker for QA."], "s": ["Every page has a title and meta description.", "No broken internal links at deploy time."], "c": ["Eleventy docs — 11ty.dev", "web.dev fast load times — web.dev/fast"], "sig": "Signature rule: Signature static templates ship a preconnect/dns-prefetch policy and an asset budget file — performance is budgeted, not hoped for.", "demo": "mkdir -p site && cat > site/index.html <<'EOF'\n<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Acme</title><meta name=\"description\" content=\"Acme site\"></head>\n<body><header><h1>Acme</h1></header><main><p>Hello.</p></main></body></html>\nEOF\ncd site && python3 -m http.server 8000 & sleep 1; curl -s -o /dev/null -w \"%{http_code}\" http://localhost:8000/; kill %1"}, {"t": "Full-Stack Template (API + SPA)", "cat": "project-templates", "d": "A full-stack template wires a JSON API backend to a single-page-app frontend with one command to run both. The layout separates client/ and server/, shares a types/ package for API contracts, proxies /api to the backend in dev, and builds the client into the server's static directory for production. The template includes auth scaffolding (session or JWT), a database migration setup, and e2e tests that hit the real API. AI full-stack builds on this template avoid the classic failure: frontend and backend disagreeing on the contract.", "h": "Scaffold client/ (Vite SPA) and server/ (API) plus shared/ for types; add a dev proxy so /api reaches the server; define the first endpoint and its TypeScript contract in shared/; write one e2e test through the real stack; then run dev and confirm the SPA renders data from the API.", "k": ["Shared types package is the contract — both sides import it.", "Dev proxy avoids CORS hacks during development.", "Production serves the built SPA from the API server.", "One e2e test through the real stack catches contract drift."], "r": ["Node 18+, a frontend bundler (Vite), an API framework.", "A database (SQLite is fine to start).", "Playwright or Cypress for e2e."], "s": ["API responses validated against the shared contract in tests.", "No secrets in client bundle; config via server-injected values."], "c": ["Vite docs — vitejs.dev", "Full-stack TypeScript patterns — typescriptlang.org"], "sig": "Signature rule: Signature full-stack templates generate the API client from the server's route definitions — the client can never disagree with the server.", "demo": "mkdir -p shared client server && cat > shared/api.d.ts <<'EOF'\nexport interface Health { ok: boolean; version: string }\nEOF\ncat > server/index.js <<'EOF'\nconst http=require('http');\nhttp.createServer((q,s)=>{s.setHeader('content-type','application/json');\ns.end(JSON.stringify({ok:true,version:'1.0.0'}));}).listen(3001);\nEOF\nnode server/index.js & sleep 1; curl -s http://localhost:3001/; kill %1"}, {"t": "pnpm Workspace Layout", "cat": "monorepo-layouts", "d": "The pnpm workspace layout is: repo root with pnpm-workspace.yaml, package.json (private), and folders apps/ for deployables plus packages/ for libraries. Apps depend on packages via workspace:* so local changes propagate without publishing. The layout adds .npmrc with shamefully-hoist=false (pnpm strictness is the point), shared configs in tooling/, and per-app Dockerfiles that copy only their dependency closure. This layout scales from 2 to 200 packages because boundaries are explicit and installs stay fast.", "h": "Create apps/ and packages/ directories, declare them in pnpm-workspace.yaml, mark root private, add workspace:* links from apps to shared packages, configure .npmrc for strictness, then install and run a cross-package build to prove the graph resolves.", "k": ["apps/ are deployable; packages/ are libraries — the split is a rule.", "workspace:* keeps local packages linked, never published mid-dev.", "Strict hoisting (shamefully-hoist=false) surfaces phantom dependencies.", "Per-app Dockerfiles copy only the app's closure for small images."], "r": ["pnpm 8+.", "A naming convention for packages (@org/name).", "CI that builds the dependency graph (turbo or nx optional)."], "s": ["Root package.json has private:true to block accidental publish.", "Every package declares its own engines and license."], "c": ["pnpm workspaces — pnpm.io/workspaces", "monorepo.tools — monorepo.tools"], "sig": "Signature rule: Signature workspaces include a dependency-cruiser config that fails CI on circular package dependencies.", "demo": "mkdir -p apps/web packages/ui && cat > pnpm-workspace.yaml <<'EOF'\npackages:\n  - 'apps/*'\n  - 'packages/*'\nEOF\ncat > apps/web/package.json <<'EOF'\n{\"name\":\"@acme/web\",\"private\":true,\"dependencies\":{\"@acme/ui\":\"workspace:*\"}}\nEOF\nmkdir -p packages/ui && echo '{\"name\":\"@acme/ui\",\"version\":\"1.0.0\",\"main\":\"index.js\"}' > packages/ui/package.json\necho \"module.exports={Button:()=>'<button/>'}\" > packages/ui/index.js\npnpm install 2>&1 | tail -1"}, {"t": "npm Workspaces Layout", "cat": "monorepo-layouts", "d": "npm workspaces (npm 7+) bring monorepo support without leaving the default toolchain: the root package.json lists workspaces: [\"packages/*\"], and npm install hoists shared dependencies to the root node_modules. It's simpler than pnpm — no new tool to install — at the cost of looser dependency isolation. The layout suits teams already on npm that want one install, shared scripts via npm run --workspaces, and per-workspace versioning. AI assistants generating npm-based monorepos should prefer this when the team refuses new tooling.", "h": "Add workspaces array to root package.json, create packages/a and packages/b with their own package.json files, run npm install once at root, verify hoisting with npm ls, then run a script across workspaces with npm run build --workspaces.", "k": ["Zero new tooling — works with stock npm 7+.", "One root lockfile; installs are a single command.", "npm run --workspaces fans scripts out to every package.", "Hoisting is looser than pnpm — audit for phantom deps."], "r": ["npm 7+.", "Node 16+.", "Consistent package naming."], "s": ["Root must be private:true.", "Workspaces cannot have conflicting peer dependency ranges silently."], "c": ["npm workspaces docs — docs.npmjs.com/cli/using-npm/workspaces", "Node.js monorepo guide — nodejs.org"], "sig": "Signature rule: Signature npm workspaces add an install-size check — if node_modules grows past the budget, CI flags the offending package.", "demo": "mkdir -p packages/a && cat > package.json <<'EOF'\n{\"name\":\"acme-npm-mono\",\"private\":true,\"workspaces\":[\"packages/*\"]}\nEOF\necho '{\"name\":\"@acme/a\",\"version\":\"1.0.0\"}' > packages/a/package.json\nnpm install --package-lock-only 2>&1 | tail -1 && npm ls --depth=0 2>/dev/null | head -5"}, {"t": "Turborepo Pipeline Layout", "cat": "monorepo-layouts", "d": "Turborepo adds a task pipeline on top of any workspace manager: turbo.json declares tasks (build depends on ^build, test, lint) and Turborepo schedules them across the package graph with remote caching. The layout puts turbo.json at the root, keeps each package's scripts standard (build/test/lint), and lets CI reuse cache hits so unchanged packages never rebuild. For AI-driven development this is gold: the pipeline encodes the correct build order, so generated code builds in the right sequence automatically.", "h": "Install turbo, write turbo.json with pipeline tasks and dependency declarations (^build), keep package scripts conventional, run turbo run build to see topological scheduling, then enable remote caching in CI for cross-run cache hits.", "k": ["turbo.json declares task dependencies — build order becomes data.", "^build means 'my dependencies build first'.", "Remote caching makes CI skip unchanged packages entirely.", "Works with npm, yarn, or pnpm underneath."], "r": ["A workspace manager already in place.", "turbo CLI (npx or global).", "CI with cache storage for remote caching."], "s": ["Every package script used by the pipeline must exit non-zero on failure.", "No task may depend on undeclared outputs."], "c": ["Turborepo docs — turbo.build/repo", "Turborepo handbook — github.com/vercel/turborepo"], "sig": "Signature rule: Signature turbo pipelines add a 'verify' task that runs after build everywhere — generation, validation, and drift-check in one command.", "demo": "cat > turbo.json <<'EOF'\n{\"$schema\":\"https://turbo.build/schema.json\",\n \"pipeline\":{\"build\":{\"dependsOn\":[\"^build\"],\"outputs\":[\"dist/**\"]},\n \"test\":{\"dependsOn\":[\"build\"]},\"lint\":{}}}\nEOF\nnpx --yes turbo --version 2>&1 | head -1"}, {"t": "Nx Integrated Repo Layout", "cat": "monorepo-layouts", "d": "Nx is the batteries-included monorepo system: generators scaffold apps and libs, the project graph visualizes dependencies, affected commands run only what changed, and computation caching speeds everything. The layout uses nx.json at root, apps/ and libs/ folders, and project.json (or package.json targets) per project. For AI-assisted teams, Nx generators are the key win — an AI can invoke the same generators humans use, producing consistent, convention-following code instead of freeform files.", "h": "Initialize with npx nx init or create-nx-workspace, generate an app and a lib with nx generators, inspect the project graph, run nx affected -t build to see change-scoped execution, then wire CI to use affected commands.", "k": ["Generators enforce conventions — AI and humans produce the same shapes.", "affected:* scopes work to what actually changed.", "Project graph makes dependency mistakes visible.", "Computation cache shared across the team via Nx Cloud (optional)."], "r": ["Node 18+.", "create-nx-workspace or nx init in an existing repo.", "CI configured for affected commands."], "s": ["Generated code must pass the repo's lint and tests.", "Project boundaries enforced via tags and lint rules."], "c": ["Nx docs — nx.dev", "Nx generators guide — nx.dev/extending-nx"], "sig": "Signature rule: Signature Nx repos tag every project with scope and type, and the linter forbids cross-scope imports that break layering.", "demo": "npx --yes create-nx-workspace@latest acme-nx --preset=ts --no-interactive --ci=skip 2>&1 | tail -2\nls acme-nx | head -5"}, {"t": "Shared Library Packages Layout", "cat": "monorepo-layouts", "d": "Shared library packages are the heart of a monorepo: packages/ui (components), packages/utils (helpers), packages/config (shared configs), packages/types (contracts). Each is independently versioned or fixed-versioned together, each has its own tests, and apps consume them via workspace links. The layout rule that matters: libraries never import from apps — dependency direction is one-way. AI refactors across the monorepo stay safe when this direction is enforced by lint (dependency-cruiser or eslint import rules).", "h": "Create packages/ui, packages/utils, packages/config, packages/types with package.json each; wire apps to them via workspace:*; add an eslint/dependency-cruiser rule forbidding packages→apps imports; then write a cross-package test proving the app renders the shared component.", "k": ["Dependency direction is one-way: apps → packages, never reverse.", "packages/types holds the contracts everything compiles against.", "Each library has its own tests — shared code gets shared scrutiny.", "Enforce direction with lint, not documentation."], "r": ["Workspace manager configured.", "A lint rule for import direction.", "Tests per library package."], "s": ["No package may import from an app.", "Public API of each package documented in its README."], "c": ["dependency-cruiser — github.com/sverweij/dependency-cruiser", "Package design — nodejs.org/en/learn"], "sig": "Signature rule: Signature libraries expose exactly one documented entry point — deep imports into internals are a lint error.", "demo": "mkdir -p packages/utils && cat > packages/utils/package.json <<'EOF'\n{\"name\":\"@acme/utils\",\"version\":\"1.0.0\",\"main\":\"index.js\",\"exports\":{\".\":\"./index.js\"}}\nEOF\necho 'exports.slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,\"-\");' > packages/utils/index.js\nnode -e \"const u=require('./packages/utils');console.log(u.slug('Hello World!'))\""}, {"t": "Versioning in Monorepos (Changesets)", "cat": "monorepo-layouts", "d": "Changesets solve monorepo versioning: each PR includes a markdown file describing which packages changed and whether the bump is major/minor/patch. On merge, the changeset bot consumes them, bumps versions, updates changelogs, and can publish. The layout adds .changeset/ config, and CI runs changeset status on PRs (failing if a changed package lacks a changeset) and changeset version/publish on main. AI-generated PRs include changesets automatically, so releases stay mechanical and human-error-free.", "h": "Init changesets, configure .changeset/config.json (fixed or independent packages), add CI check that PRs touching packages include a changeset file, wire the version+publish action on main, then cut a test changeset and watch the bot open the version PR.", "k": ["Every package-changing PR carries a changeset — enforced by CI.", "Bump type (major/minor/patch) is a deliberate human (or AI) decision.", "Changelogs generated from changesets — never hand-written.", "Publish happens from the version PR, not from local machines."], "r": ["changesets CLI.", "CI with npm publish permissions (OIDC preferred).", "A clear fixed-vs-independent package policy."], "s": ["No manual version edits in package.json — changesets own versions.", "Private packages excluded from publishing via config."], "c": ["Changesets docs — github.com/changesets/changesets", "Semantic versioning — semver.org"], "sig": "Signature rule: Signature changesets require a one-line user-impact note — the changelog is written for users, not for git.", "demo": "npx --yes @changesets/cli init 2>&1 | tail -1\ncat > .changeset/tidy-pandas.md <<'EOF'\n---\n\"@acme/utils\": patch\n---\n\nFix slug edge case for unicode input.\nEOF\nls .changeset/"}, {"t": "Monorepo CI Layout", "cat": "monorepo-layouts", "d": "Monorepo CI must be change-aware or it becomes slow and flaky: the layout runs install once, then uses affected/turbo scoping to build, lint, and test only changed packages plus their dependents. The workflow caches the package-manager store and the build cache, runs a fast 'is-affected' gate for docs-only PRs, and fans out package jobs in a matrix. AI-generated changes get the same scoped pipeline — small diffs get fast feedback, and the main branch stays green because every package's tests actually ran.", "h": "Write a CI workflow that installs once with store caching, computes affected packages, runs build/lint/test scoped to affected plus dependents, uploads the build cache, then verify with a docs-only PR (skips heavy jobs) and a cross-package PR (runs dependents' tests).", "k": ["Affected-scoping keeps CI fast as the repo grows.", "Cache the package store AND the build cache — both matter.", "Docs-only changes skip build/test via path filters.", "Dependents' tests run too — a library change can break its consumers."], "r": ["CI with caching (GitHub Actions cache).", "Affected detection (turbo/nx or path filters).", "A green main branch policy."], "s": ["CI must be reproducible: same commit, same result.", "No secrets in logs; mask tokens."], "c": ["GitHub Actions caching — docs.github.com/actions/using-workflows/caching", "Turborepo CI guide — turbo.build/repo/docs/ci"], "sig": "Signature rule: Signature monorepo CI fails if any package's coverage drops below its recorded floor — coverage is a ratchet, not a suggestion.", "demo": "cat > .github/workflows/ci.yml <<'EOF'\nname: ci\non: [push, pull_request]\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: pnpm/action-setup@v2\n      - run: pnpm install --frozen-lockfile\n      - run: pnpm -r --filter \"...[HEAD~1]\" build\nEOF\necho \"ci layout written\""}, {"t": "SaaS Starter Kit Anatomy", "cat": "starter-kits", "d": "A SaaS starter kit is a product skeleton: auth (signup/login/teams), billing (Stripe subscriptions with webhooks), database with migrations, email sending, an admin dashboard, and a marketing landing page — all wired together. The value is integration: auth talks to billing talks to teams without you writing glue. Evaluate kits by what they DON'T make you build: user management, subscription lifecycle, and webhook idempotency are the hard parts. AI product builds start from a kit and spend effort on the differentiating feature, not on login forms.", "h": "Pick a kit matching your stack, configure env vars (database URL, Stripe keys, email provider), run migrations, create a test user, walk the full signup→subscribe→cancel flow in Stripe test mode, then delete the demo data and start building your feature on top.", "k": ["Auth + billing + teams integration is the kit's real value.", "Test the full subscription lifecycle in test mode before building.", "Webhook handlers must be idempotent — Stripe retries.", "Keep the marketing page in the same repo for consistent deploys."], "r": ["A kit for your stack (e.g., Next.js SaaS starters).", "Stripe test account, a database, an email provider.", "Env vars for all three before first run."], "s": ["No live charges during development — test mode only.", "Customer data handling documented (GDPR basics)."], "c": ["Stripe billing docs — stripe.com/docs/billing", "SaaS starter comparisons — saasframe.io"], "sig": "Signature rule: Signature SaaS kits include a billing self-test that runs the whole subscribe/cancel cycle against Stripe test mode on every deploy.", "demo": "cat > billing-check.js <<'EOF'\n// idempotency-keyed webhook handler sketch\nconst seen=new Set();\nfunction onWebhook(event){\n  if(seen.has(event.id)) return 'duplicate-ignored';\n  seen.add(event.id);\n  return 'handled:'+event.type;\n}\nconsole.log(onWebhook({id:'evt_1',type:'customer.subscription.created'}));\nconsole.log(onWebhook({id:'evt_1',type:'customer.subscription.created'}));\nEOF\nnode billing-check.js"}, {"t": "Blog Starter Kit", "cat": "starter-kits", "d": "A blog starter kit gives markdown-driven publishing: posts as markdown files with frontmatter (title, date, tags), automatic RSS, sitemap, tag pages, syntax-highlighted code blocks, and SEO meta per post. The best kits keep content as files in git — writing is a commit, history is free, and AI can draft posts as markdown directly. Look for kits with draft support, reading-time estimates, and an RSS feed, because those are the features every blog eventually needs and nobody wants to build twice.", "h": "Scaffold the kit, write a first post in markdown with frontmatter, verify the RSS feed and sitemap include it, check code-block highlighting with a sample snippet, then deploy and confirm the feed validates.", "k": ["Content as markdown files in git — history and diffs for free.", "RSS + sitemap + per-post SEO meta are non-negotiable.", "Draft posts stay unpublished until you flip the flag.", "AI drafts posts as markdown; the kit handles the rest."], "r": ["A static generator or markdown blog kit.", "An RSS validator for QA.", "A host for static files."], "s": ["Every post has title, date, and description frontmatter.", "Feed validates at validator.w3.org/feed."], "c": ["RSS 2.0 spec — cyber.harvard.edu/rss/rss.html", "Eleventy blogging — 11ty.dev"], "sig": "Signature rule: Signature blog kits auto-generate a post's description from its first paragraph if missing — no post ships without meta.", "demo": "mkdir -p posts && cat > posts/hello.md <<'EOF'\n---\ntitle: Hello\ndate: 2026-01-01\ntags: [intro]\n---\n\nFirst post. `code` looks like this.\nEOF\nnode -e \"\nconst fs=require('fs');const t=fs.readFileSync('posts/hello.md','utf8');\nconst m=t.match(/---([\\s\\S]*?)---/);console.log('frontmatter found:',!!m);console.log('has title:',/title:/.test(m[1]));\""}, {"t": "E-commerce Starter Kit", "cat": "starter-kits", "d": "An e-commerce starter kit provides the storefront skeleton: product catalog pages, cart state, checkout flow wired to a payment provider, order confirmation, and an admin view of orders. The critical integration is the payment webhook → order fulfillment chain, which must be idempotent and logged. Kits differ on inventory (digital vs physical), tax, and shipping — pick the kit whose assumptions match your products. AI storefront builds customize theme and catalog while the money path stays battle-tested.", "h": "Configure the kit with test payment keys, create two test products, run a full purchase in test mode, verify the webhook creates the order exactly once (replay it to prove idempotency), then check the admin order view before theming.", "k": ["Money path first: purchase → webhook → order, idempotent.", "Test mode end-to-end before any theming.", "Inventory model must match your products (digital vs physical).", "Admin order view is part of the kit — verify it early."], "r": ["Payment provider test keys (Stripe).", "Product data (even two items).", "Webhook forwarding for local testing (stripe listen)."], "s": ["Never process the same payment event twice — idempotency keys.", "PCI scope minimized by using hosted checkout fields."], "c": ["Stripe checkout docs — stripe.com/docs/payments/checkout", "E-commerce checklist — baymard.com/checklist"], "sig": "Signature rule: Signature commerce kits replay every webhook in a sandbox on deploy — the money path is proven, not assumed.", "demo": "node -e \"\nconst orders=new Map();\nfunction fulfill(eventId,order){if(orders.has(eventId))return 'duplicate';orders.set(eventId,order);return 'fulfilled';}\nconsole.log(fulfill('evt_9',{total:1999}));\nconsole.log(fulfill('evt_9',{total:1999}));\nconsole.log('orders:',orders.size);\""}, {"t": "Dashboard/Admin Starter Kit", "cat": "starter-kits", "d": "An admin dashboard kit gives the internal-tool UI: sidebar navigation, data tables with sorting/filtering/pagination, forms with validation, charts, role-based access, and an audit log. Internal tools live or die on the table component — pick a kit whose table handles 10k rows with virtualization. The kit should separate admin auth from customer auth (different session, stricter rules). AI-generated internal tools on this kit look professional because the kit's design system does the heavy lifting.", "h": "Scaffold the kit, connect it to a real data source, build one CRUD table with server-side pagination, add a role gate hiding admin routes from non-admins, write an audit-log entry on every mutation, then load 10k rows and verify the table stays smooth.", "k": ["Table component quality decides the kit — test with 10k rows.", "Admin auth separate from customer auth, stricter rules.", "Every mutation writes an audit-log entry.", "Server-side pagination — never ship full datasets to the browser."], "r": ["A data source to administer.", "Role definitions (admin, viewer).", "An audit log store."], "s": ["Admin routes require authentication AND role check.", "Audit log is append-only."], "c": ["Admin UI patterns — uxbarn.com/admin-dashboard", "OWASP access control — owasp.org"], "sig": "Signature rule: Signature admin kits watermark every data export with who/when — leaks are traceable by construction.", "demo": "node -e \"\n// server-side pagination sketch\nconst rows=Array.from({length:10000},(_,i)=>({id:i,name:'row'+i}));\nfunction page(p,per){return rows.slice(p*per,(p+1)*per);}\nconst t0=Date.now();const r=page(3,50);\nconsole.log('page 4:',r.length,'rows in',Date.now()-t0,'ms');\nconsole.log('first:',JSON.stringify(r[0]));\""}, {"t": "Mobile App Starter (React Native)", "cat": "starter-kits", "d": "A React Native starter kit (Expo is the sane default) provides navigation, auth storage, push notifications, over-the-air updates, and app-store build config. Expo's managed workflow removes native build pain — the kit builds binaries in the cloud. Key kit features: deep linking config, secure token storage (expo-secure-store, never AsyncStorage for tokens), and an update strategy (OTA for JS, store review for native changes). AI mobile builds on Expo avoid the native toolchain entirely until the app needs a custom native module.", "h": "Scaffold with create-expo-app, configure navigation (stack + tabs) and deep links, store auth tokens in secure storage, set up EAS builds for both stores, push one OTA update to a test device, then verify the store metadata (screenshots, description) is in the repo.", "k": ["Expo managed workflow first — eject only with a native reason.", "Tokens in secure storage, never plain AsyncStorage.", "OTA updates for JS; store releases for native changes.", "Deep links configured from day one — adding later is painful."], "r": ["Expo CLI and an Expo account.", "EAS configured for builds.", "Test devices or simulators for both platforms."], "s": ["No secrets in the JS bundle — use EAS secrets.", "App privacy labels filled before submission."], "c": ["Expo docs — docs.expo.dev", "EAS build — docs.expo.dev/build/introduction"], "sig": "Signature rule: Signature mobile kits gate OTA updates behind a staged rollout flag — a bad update reaches 1% first, not 100%.", "demo": "node -e \"\n// navigation + deep-link config sketch\nconst linking={prefixes:['acme://'],config:{screens:{Home:'home',Profile:'user/:id'}}};\nfunction parse(url){const m=url.match(/acme:\\/\\/user\\/(\\w+)/);return m?{screen:'Profile',params:{id:m[1]}}:{screen:'Home'}};\nconsole.log(JSON.stringify(parse('acme://user/42')));\""}, {"t": "API-Only Starter Kit", "cat": "starter-kits", "d": "An API-only starter kit is a backend without a frontend: structured routing, request validation, auth middleware, database layer with migrations, OpenAPI spec generation, rate limiting, and structured logging. No templates, no static assets — just JSON in and out. The kit's OpenAPI spec is the product: generate it from code annotations so docs never drift. AI API builds on this kit get validation, auth, and docs for free and can focus on the domain logic.", "h": "Scaffold the kit, define one resource with validation schemas, enable auth middleware, generate the OpenAPI spec from annotations, write contract tests asserting responses match the spec, then run the kit and fetch the docs endpoint.", "k": ["OpenAPI generated from code — docs can't drift.", "Validation schemas on every input; reject unknown fields.", "Auth middleware applied globally, opted out per-route explicitly.", "Contract tests assert responses match the spec."], "r": ["A web framework (Express/Fastify/Hono).", "A validator (zod/ajv).", "A database or in-memory store to start."], "s": ["All inputs validated; all errors a consistent JSON shape.", "Rate limits on from day one."], "c": ["OpenAPI spec — spec.openapis.org", "API design guide — docs.microsoft.com/rest/api-guidelines"], "sig": "Signature rule: Signature API kits run a breaking-change detector in CI — a removed field fails the build before it breaks clients.", "demo": "node -e \"\n// validation sketch with a tiny schema\nfunction validate(body){const e=[];\n if(typeof body.name!=='string'||!body.name.trim())e.push('name required');\n if(body.age!==undefined&&(!Number.isInteger(body.age)||body.age<0))e.push('age invalid');\n return e;}\nconsole.log(validate({name:'Ada',age:36}));\nconsole.log(validate({name:'',age:-1}));\""}, {"t": "Chrome Extension Starter Kit", "cat": "starter-kits", "d": "A Chrome extension starter (Manifest V3) needs: manifest.json with minimal permissions, a service worker background script, content scripts with narrow match patterns, a popup UI, options page, and storage via chrome.storage. V3 killed remote code and background pages — the kit must be V3-native, not a V2 port. The permission model is the design constraint: request the narrowest host permissions possible, because every permission is a review risk and a user-trust cost. AI extension builds on a V3 kit avoid the classic rejection reasons.", "h": "Scaffold the V3 kit, declare only needed permissions, implement the content script with the narrowest matches, build the popup, load unpacked in chrome://extensions, test on the target sites, then package and run a permission audit before submission.", "k": ["Manifest V3 only — V2 is dead.", "Narrowest permissions and match patterns win reviews.", "No remote code — all code bundled and reviewed.", "chrome.storage for state; respect user data."], "r": ["Chrome/Edge for testing.", "A build step (Vite works well).", "Web store developer account for publishing."], "s": ["Justify every permission in the store listing.", "No collecting data beyond the stated purpose."], "c": ["Chrome extensions docs — developer.chrome.com/docs/extensions", "Manifest V3 migration — developer.chrome.com/docs/extensions/migrating"], "sig": "Signature rule: Signature extension kits include a permission-lint that fails the build on broad host patterns like *://*/*.", "demo": "cat > manifest.json <<'EOF'\n{\"manifest_version\":3,\"name\":\"Acme Highlighter\",\"version\":\"1.0.0\",\n \"permissions\":[\"storage\"],\n \"action\":{\"default_popup\":\"popup.html\"},\n \"content_scripts\":[{\"matches\":[\"https://example.com/*\"],\"js\":[\"content.js\"]}]}\nEOF\nnode -e \"const m=require('./manifest.json');console.log('mv'+m.manifest_version,'permissions:',m.permissions.join(','))\""}, {"t": "Vite Build Config from Scratch", "cat": "build-configs", "d": "A hand-written vite.config.js teaches what the magic does: plugins array (React/Vue/Svelte), resolve.alias for @/ imports, server.proxy for API dev, build.rollupOptions for chunking, and define for env constants. Vite's dev server uses native ESM (no bundling in dev — instant start) and Rollup for production builds. Writing the config yourself matters because AI-generated projects inherit configs nobody understands; when the build breaks, the person who wrote the config fixes it in minutes instead of hours.", "h": "Write vite.config.js with the framework plugin, an @ alias, a dev proxy for /api, and manual chunk splitting for vendor code; run dev and confirm HMR works; run build and inspect the output chunks; then document each option with a one-line comment.", "k": ["Dev uses native ESM (fast); build uses Rollup (optimized) — know which you're configuring.", "resolve.alias @/ keeps imports clean.", "server.proxy removes CORS pain in development.", "Manual chunks keep vendor code cached across deploys."], "r": ["Vite 5+.", "Your framework plugin.", "A backend or mock for the proxy."], "s": ["Build output analyzed before shipping (no 5MB bundles).", "Env vars prefixed properly (VITE_) or they won't ship."], "c": ["Vite config reference — vitejs.dev/config", "Rollup options — rollupjs.org/configuration-options"], "sig": "Signature rule: Signature Vite configs fail the build when any chunk exceeds the recorded budget — bundle size is a CI gate.", "demo": "cat > vite.config.js <<'EOF'\nimport {defineConfig} from 'vite';\nexport default defineConfig({\n  resolve:{alias:{'@':'/src'}},\n  server:{proxy:{'/api':'http://localhost:3001'}},\n  build:{rollupOptions:{output:{manualChunks:{vendor:['react','react-dom']}}}}\n});\nEOF\necho \"vite config written\" && node -e \"console.log('alias @ -> /src, proxy /api -> :3001')\""}, {"t": "Webpack Config Essentials", "cat": "build-configs", "d": "Webpack is still the configurable workhorse: entry, output, module.rules (loaders for js/css/assets), plugins (HtmlWebpackPlugin, DefinePlugin), resolve, devServer, and optimization.splitChunks. You reach for webpack when you need loaders for exotic assets or a mature plugin ecosystem. The essential config is smaller than its reputation: entry + babel-loader + css + HtmlWebpackPlugin covers most apps. AI projects that eject from zero-config tools land here — understanding these six sections is the whole game.", "h": "Write webpack.config.js with entry/output, babel-loader for JS, style/css loaders, HtmlWebpackPlugin, and splitChunks for vendors; run a dev server; run a production build; then compare bundle sizes before and after enabling splitChunks.", "k": ["Six sections cover 90%: entry, output, rules, plugins, devServer, optimization.", "Loaders transform files; plugins transform the build.", "splitChunks extracts vendors for long-term caching.", "Dev uses cheap sourcemaps; prod uses hidden or none."], "r": ["webpack 5 + webpack-cli.", "babel-loader or swc-loader.", "HtmlWebpackPlugin."], "s": ["Production builds minified with deterministic chunk names.", "No dev-only code in prod bundles (DefinePlugin NODE_ENV)."], "c": ["Webpack concepts — webpack.js.org/concepts", "Webpack configuration — webpack.js.org/configuration"], "sig": "Signature rule: Signature webpack configs pin loader versions and fail on version drift — build reproducibility is non-negotiable.", "demo": "cat > webpack.config.js <<'EOF'\nconst Html=require('html-webpack-plugin');\nmodule.exports={entry:'./src/index.js',\n output:{filename:'[name].[contenthash].js',clean:true},\n module:{rules:[{test:/\\.js$/,use:'babel-loader',exclude:/node_modules/},\n {test:/\\.css$/,use:['style-loader','css-loader']}]},\n plugins:[new Html({template:'./src/index.html'})],\n optimization:{splitChunks:{chunks:'all'}}};\nEOF\necho \"webpack config written\""}, {"t": "TypeScript Config (tsconfig) Done Right", "cat": "build-configs", "d": "A correct tsconfig.json is strict:true plus moduleResolution:\"bundler\" (for Vite/webpack), target matching your runtime, and path aliases mirroring the bundler's. The mistakes to avoid: strict:false (defeats the purpose), skipLibCheck:false slowing builds, and allowJs without checkJs creating a type twilight zone. For monorepos, a root tsconfig.base.json with per-package extends keeps settings consistent. AI TypeScript output is dramatically better with strict on — the compiler becomes the AI's reviewer.", "h": "Write tsconfig.json with strict:true, moduleResolution bundler, target ES2022, paths for @/*; add a root base config if in a monorepo; run tsc --noEmit and fix every error; then enable noUncheckedIndexedAccess for the full strict experience.", "k": ["strict:true is the whole point — never ship strict:false.", "moduleResolution:bundler matches modern bundlers.", "Path aliases must mirror the bundler's resolve.alias.", "Monorepos share a tsconfig.base.json via extends."], "r": ["TypeScript 5+.", "A bundler or runtime that matches moduleResolution.", "tsc --noEmit in CI."], "s": ["tsc --noEmit passes with zero errors before merge.", "No @ts-ignore without a linked reason."], "c": ["tsconfig reference — typescriptlang.org/tsconfig", "TypeScript handbook — typescriptlang.org/docs/handbook"], "sig": "Signature rule: Signature tsconfigs enable noUncheckedIndexedAccess — array indexing returns T|undefined and the code proves safety.", "demo": "cat > tsconfig.json <<'EOF'\n{\"compilerOptions\":{\"strict\":true,\"target\":\"ES2022\",\n \"module\":\"ESNext\",\"moduleResolution\":\"bundler\",\n \"paths\":{\"@/*\":[\"./src/*\"]},\"noUncheckedIndexedAccess\":true,\n \"skipLibCheck\":true},\"include\":[\"src\"]}\nEOF\nnpx --yes -p typescript tsc --noEmit -p tsconfig.json 2>&1 | head -3; echo \"tsc check done\""}, {"t": "ESLint + Prettier Config", "cat": "build-configs", "d": "ESLint catches bugs, Prettier formats code — run both, let each do its job, and never let them fight (eslint-config-prettier disables formatting rules in ESLint). The modern setup uses eslint.config.js flat config, typescript-eslint for TS, and per-file overrides. Prettier's config is tiny: singleQuote, trailingComma, printWidth. The AI angle: lint rules are machine-enforceable code review — an AI that writes code passing your lint config writes code your team accepts.", "h": "Write eslint.config.js (flat config) with recommended sets for JS/TS, add eslint-config-prettier last, write .prettierrc, add lint and format:check scripts, run both on the codebase, fix or document every finding, then enforce in CI.", "k": ["ESLint for correctness, Prettier for formatting — separate jobs.", "eslint-config-prettier prevents rule conflicts.", "Flat config (eslint.config.js) is the modern format.", "CI runs lint; pre-commit hook runs it faster."], "r": ["ESLint 9 (flat config).", "Prettier 3.", "typescript-eslint if using TS."], "s": ["Zero lint errors on main — warnings are errors in CI.", "Formatting checked in CI, not just locally."], "c": ["ESLint docs — eslint.org", "Prettier options — prettier.io/docs/en/options"], "sig": "Signature rule: Signature lint configs ban console.log in src/ — logging goes through the app logger or it doesn't ship.", "demo": "cat > eslint.config.js <<'EOF'\nimport js from '@eslint/js';\nimport prettier from 'eslint-config-prettier';\nexport default [js.configs.recommended, prettier,\n {rules:{'no-console':'warn','no-unused-vars':'error'}}];\nEOF\ncat > .prettierrc <<'EOF'\n{\"singleQuote\":true,\"trailingComma\":\"all\",\"printWidth\":100}\nEOF\necho \"lint configs written\""}, {"t": "Babel vs SWC vs esbuild Choice", "cat": "build-configs", "d": "Three transpilers, three trade-offs: Babel is the most compatible (every plugin exists) but slowest; SWC is Rust-fast and webpack/next-compatible with near-Babel features; esbuild is fastest of all but does transpile-only (no type-checking, limited Babel plugin parity). Rule of thumb: esbuild for dev speed and simple builds, SWC when you need speed plus broad compatibility (Next.js default), Babel when you depend on exotic plugins. AI-generated build setups should default to SWC/esbuild and only reach for Babel with a named reason.", "h": "Benchmark your actual codebase with each transpiler, check plugin requirements (do you need a Babel-only plugin?), measure CI build times, then choose and document the reason in the build config's comments.", "k": ["esbuild: fastest, transpile-only, dev-speed king.", "SWC: Rust speed with Babel-class compatibility.", "Babel: slowest, but every plugin ever written exists.", "Type-checking is separate (tsc) with SWC/esbuild — plan for it."], "r": ["A real codebase to benchmark.", "Build timing harness.", "Plugin inventory."], "s": ["Choice documented with measured numbers, not vibes.", "Type checking still runs somewhere (tsc --noEmit)."], "c": ["SWC docs — swc.rs", "esbuild docs — esbuild.github.io"], "sig": "Signature rule: Signature builds record transpile+typecheck times in CI artifacts — build performance is tracked like any metric.", "demo": "node -e \"\nconst speeds={esbuild:'~10-100x',swc:'~20x vs babel',babel:'1x baseline'};\nconsole.log('relative transpile speed:');\nfor(const [k,v] of Object.entries(speeds))console.log(' '+k+': '+v);\""}, {"t": "Environment-Based Build Modes", "cat": "build-configs", "d": "Build modes (development/staging/production) change what gets bundled: dev keeps sourcemaps and debug flags, staging mirrors prod with test backends, production minifies, tree-shakes, and strips dev code. Implement with .env files per mode plus a build-time define (import.meta.env.MODE / process.env.NODE_ENV). The critical rule: secrets never enter the client bundle — only public-prefixed vars ship. AI deploys pick the mode explicitly; 'it worked in dev' failures almost always trace to a mode difference.", "h": "Define .env.development/.env.staging/.env.production, wire the bundler's mode flag to pick the right file, add a build script per mode, verify staging behaves like prod against test backends, then audit the prod bundle for leaked secrets.", "k": ["Three modes minimum: dev, staging (prod-like), production.", "Staging must mirror prod config against test backends.", "Only public-prefixed vars reach the client bundle.", "Build mode explicit in every deploy command."], "r": ["A bundler with mode support.", "Per-mode env files.", "A staging environment."], "s": ["No secrets in client bundles — audit the output.", "Production builds reproducible from the same commit."], "c": ["Vite env modes — vitejs.dev/guide/env-and-mode", "12-factor config — 12factor.net/config"], "sig": "Signature rule: Signature builds embed the git SHA and mode into a /version endpoint — every deploy is identifiable.", "demo": "cat > .env.production <<'EOF'\nVITE_API_URL=https://api.acme.com\nVITE_MODE=production\nEOF\nnode -e \"\nconst mode=process.env.BUILD_MODE||'development';\nconst cfg={development:{debug:true},staging:{debug:false,backend:'test'},production:{debug:false,backend:'live'}}[mode];\nconsole.log(mode,'=>',JSON.stringify(cfg));\""}, {"t": "Build Output Analysis", "cat": "build-configs", "d": "Analyzing build output means knowing what's in your bundle: run a bundle analyzer (rollup-plugin-visualizer, webpack-bundle-analyzer) and read the treemap. The usual suspects are huge: a date library imported whole, lodash without cherry-picking, duplicate dependencies from mismatched versions, and unoptimized images. Set a budget (e.g., 200KB gzipped initial JS) and fail CI when it's exceeded. AI-generated features tend to add dependencies casually — the analyzer plus budget turns 'npm install' into a deliberate act.", "h": "Add the bundle analyzer plugin, build for production, open the treemap, identify the three largest modules, replace or cherry-pick the worst offenders, set a CI size budget, then re-build and confirm the budget passes.", "k": ["Treemap first — optimize what the data shows, not what you guess.", "Duplicate deps from version mismatches are silent killers.", "Budget in CI turns size into a reviewed decision.", "Images and fonts count — they're often bigger than the JS."], "r": ["A bundle analyzer plugin.", "A production build.", "A size budget number the team agrees on."], "s": ["Initial JS budget enforced in CI.", "No duplicate major versions of the same library."], "c": ["rollup-plugin-visualizer — github.com/btd/rollup-plugin-visualizer", "web.dev bundle guide — web.dev/articles/reduce-javascript-payloads"], "sig": "Signature rule: Signature repos store the analyzer report as a CI artifact on every main build — bundle history is visible, not tribal knowledge.", "demo": "node -e \"\n// fake bundle inventory -> find offenders over budget\nconst mods=[['app',42],['react-dom',131],['moment',290],['lodash',72],['charts',188]];\nconst budget=200;\nmods.filter(m=>m[1]>budget).forEach(m=>console.log('OVER BUDGET:',m[0],m[1]+'KB'));\""}, {"t": ".env Strategy: Local vs Staging vs Prod", "cat": "env-setup", "d": ".env strategy is: .env.example committed (every variable documented, empty values), .env.local gitignored (real local secrets), and staging/prod values injected by the deploy platform — never committed. Load order: platform env wins over files. The .env.example is a contract: if CI or a teammate can't set up from it alone, it's incomplete. AI dev environments read .env.example to know what to ask for, and never invent variable names.", "h": "Write .env.example with every variable and a comment per variable, gitignore .env.local, configure the deploy platform's env for staging and prod, add a startup check that fails fast on missing required vars, then onboard a fresh clone using only .env.example.", "k": [".env.example is committed and complete — it's the contract.", "Real secrets live in the platform, never in git.", "Startup validates required vars and fails fast with names.", "AI asks for values based on .env.example, never invents names."], "r": ["A deploy platform with env management.", "gitignore covering .env*.local.", "A startup validation function."], "s": ["No .env files with secrets committed — ever.", "Variable names stable across environments."], "c": ["12-factor config — 12factor.net/config", "dotenv docs — github.com/motdotla/dotenv"], "sig": "Signature rule: Signature .env.example includes a 'rotation' note per secret — every secret documents how to rotate it.", "demo": "cat > .env.example <<'EOF'\n# Database connection string (postgres). Rotate via hosting dashboard.\nDATABASE_URL=\n# Public API base URL (safe for client)\nVITE_API_URL=http://localhost:3001\nEOF\nnode -e \"\nconst required=['DATABASE_URL'];const missing=required.filter(k=>!process.env[k]);\nif(missing.length){console.log('missing:',missing.join(','));process.exit(0);}\""}, {"t": "Dev Container Setup (VS Code)", "cat": "env-setup", "d": "A dev container (.devcontainer/devcontainer.json) gives every contributor — human or AI — the identical environment: same Node/Python versions, same extensions, same tools, built by Docker. 'Works on my machine' dies because there is only one machine: the container. The config specifies the image, features (node, python, docker-in-docker), VS Code extensions, and post-create commands (install deps). AI coding agents run inside the same container, so their tool versions match yours exactly.", "h": "Write .devcontainer/devcontainer.json with the base image, language features, extensions list, and postCreateCommand running the install; rebuild the container; open the project inside it; verify versions match CI; then document 'open in container' as the onboarding step.", "k": ["One container definition = one true environment.", "Extensions pinned in the config, not installed by memory.", "postCreateCommand installs deps automatically.", "AI agents run in the same container as humans."], "r": ["Docker + VS Code with Dev Containers extension.", "A base image matching production's runtime.", "The install command for the project."], "s": ["Container builds from scratch without manual steps.", "Versions in container match CI exactly."], "c": ["Dev containers spec — containers.dev", "VS Code dev containers — code.visualstudio.com/docs/devcontainers"], "sig": "Signature rule: Signature devcontainers run a version-parity check on create — container vs CI mismatch fails loudly on day one.", "demo": "mkdir -p .devcontainer && cat > .devcontainer/devcontainer.json <<'EOF'\n{\"name\":\"acme-dev\",\"image\":\"mcr.microsoft.com/devcontainers/javascript-node:20\",\n \"features\":{\"ghcr.io/devcontainers/features/docker-in-docker:2\":{}},\n \"customizations\":{\"vscode\":{\"extensions\":[\"dbaeumer.vscode-eslint\",\"esbenp.prettier-vscode\"]}},\n \"postCreateCommand\":\"npm install\"}\nEOF\necho \"devcontainer written\""}, {"t": "direnv + asdf Version Pinning", "cat": "env-setup", "d": "direnv auto-loads .envrc when you cd into the project (and unloads on leave); asdf manages tool versions via .tool-versions (nodejs 20.11.0, python 3.12.1). Together they mean the right versions are active just by entering the directory — no manual switching, no 'wrong node' bugs. .envrc can also lay out project-local binaries (PATH_add bin) and load .env. AI shell sessions source the same .envrc, so generated commands run against the project's pinned toolchain.", "h": "Install direnv and asdf, write .tool-versions with exact versions, write .envrc (layout node, PATH_add, dotenv), run direnv allow, cd out and back in to verify versions switch, then confirm CI installs the same versions from .tool-versions.", "k": [".tool-versions pins exact versions — the whole team shares them.", "direnv activates on cd — no manual switching.", "Project-local bin/ on PATH keeps tooling hermetic.", "CI reads the same .tool-versions file."], "r": ["direnv + asdf installed.", "Shell hook for direnv.", "CI support for asdf or equivalent."], "s": ["Versions pinned exactly, not as ranges.", ".envrc reviewed — it executes on cd."], "c": ["direnv docs — direnv.net", "asdf docs — asdf-vm.com"], "sig": "Signature rule: Signature .envrc files are allowlisted by checksum in team docs — a changed .envrc is a reviewed event.", "demo": "cat > .tool-versions <<'EOF'\nnodejs 20.11.0\npython 3.12.1\nEOF\ncat > .envrc <<'EOF'\nlayout node\nPATH_add bin\ndotenv .env.local\nEOF\necho \"pinning written:\" && cat .tool-versions"}, {"t": "Makefile for Common Tasks", "cat": "env-setup", "d": "A Makefile is the project's command palette: make setup, make dev, make test, make build, make deploy — one canonical spelling for every task, self-documenting via make help. It wraps the real commands (npm/pnpm/docker) so contributors memorize five targets, not fifty flags. AI agents read the Makefile to learn the project's workflows instead of guessing commands. Keep recipes short, use .PHONY, and make help the default target.", "h": "Write a Makefile with setup/dev/test/build/deploy targets plus a help target listing them, mark all as .PHONY, replace README command snippets with make targets, then run make help and verify every target works from a clean clone.", "k": ["Five canonical targets beat fifty memorized flags.", "make help is self-documentation — keep it current.", ".PHONY on every target — files named 'test' break make.", "AI reads the Makefile to learn project workflows."], "r": ["make (or a compatible runner).", "The underlying commands (npm/docker).", "README updated to reference make targets."], "s": ["Every target works from a clean clone.", "make help lists all targets with descriptions."], "c": ["GNU make manual — gnu.org/software/make/manual", "Makefile style guide — style.maker"], "sig": "Signature rule: Signature Makefiles start with a guard that fails if required tools are missing — with install hints per tool.", "demo": "cat > Makefile <<'EOF'\n.PHONY: help setup dev test build\nhelp: ## show targets\n\t@grep -E '^[a-z]+:.*##' $(MAKEFILE_LIST) | sort\nsetup: ## install dependencies\n\tnpm install\ndev: ## run dev server\n\tnpm run dev\ntest: ## run tests\n\tnpm test\nbuild: ## production build\n\tnpm run build\nEOF\nmake help"}, {"t": "Git Hooks via Husky", "cat": "env-setup", "d": "Husky wires git hooks to npm scripts: pre-commit runs lint-staged (lint + format only changed files), commit-msg validates conventional-commit format, pre-push runs the fast test suite. Hooks are the last automated checkpoint before code enters history — they catch what CI would catch, earlier. Keep hooks fast (under 10 seconds) or developers bypass them; heavy checks belong in CI. AI commits go through the same hooks, so generated code meets the bar automatically.", "h": "Install husky, init it, add a pre-commit hook running lint-staged, add commit-msg hook validating the message format, keep each hook under 10s, test by making a bad commit (it should refuse), then document bypass policy (never bypass without reason).", "k": ["Hooks catch issues before history, not after.", "Keep hooks under 10 seconds or they get bypassed.", "lint-staged: only touch changed files.", "commit-msg hook enforces the message convention."], "r": ["husky + lint-staged.", "A commit message convention.", "Fast lint/test scripts."], "s": ["Hooks installed automatically on setup (prepare script).", "Bypass (--no-verify) requires a stated reason."], "c": ["husky docs — typicode.github.io/husky", "lint-staged — github.com/lint-staged/lint-staged"], "sig": "Signature rule: Signature repos log hook bypasses — --no-verify usage appears in the PR as a visible note.", "demo": "npx --yes husky init 2>&1 | tail -1\ncat > .husky/pre-commit <<'EOF'\nnpx lint-staged\nEOF\ncat > .husky/commit-msg <<'EOF'\nnpx --no-install commitlint --edit \"$1\"\nEOF\nchmod +x .husky/pre-commit .husky/commit-msg && echo \"hooks installed\""}, {"t": "README-Driven Setup (Onboarding in 5 Minutes)", "cat": "env-setup", "d": "README-driven setup means the README's 'Getting started' section is tested: a fresh clone following only the README reaches a running app in under five minutes. Write prerequisites (versions), then numbered commands: clone, install, configure env from .env.example, migrate, seed, run. Then actually test it — wipe and follow your own instructions. AI onboarding reads the same README; if a human can't follow it, the AI can't either. Time the run and put the measured time in the README as a promise.", "h": "Write the numbered setup steps, test them on a clean machine or container following only the README, time the run, fix every snag found, record the measured time in the README, then re-test quarterly or when setup changes.", "k": ["Test onboarding on a clean machine following only the README.", "Numbered steps, copy-pasteable commands, expected outputs.", "Measured setup time published as a promise.", "AI and humans onboard from the same document."], "r": ["A clean test environment.", "A timer.", "Willingness to fix every snag found."], "s": ["Setup completes in under 5 minutes on a typical machine.", "Every command's expected output shown."], "c": ["README best practices — github.com/matiassingers/awesome-readme", "Onboarding docs — docs.github.com"], "sig": "Signature rule: Signature READMEs include a setup self-test script — new contributors run one command that verifies every prerequisite.", "demo": "cat > setup-check.sh <<'EOF'\n#!/bin/sh\nset -e\ncommand -v node >/dev/null || { echo \"MISSING: node\"; exit 1; }\ncommand -v npm >/dev/null || { echo \"MISSING: npm\"; exit 1; }\ntest -f .env.example || { echo \"MISSING: .env.example\"; exit 1; }\necho \"prerequisites OK: $(node --version)\" \nEOF\nchmod +x setup-check.sh && ./setup-check.sh"}];
function ladderTier(r){return r<=2?"Foundations":(r<=4?"Compounded":"Advanced");}
function generate(seed,opts){
  opts=opts||{};
  var n=DATA.length;
  var e=DATA[(seed-1)%n];
  var cycle=Math.floor((seed-1)/n);
  var ladder=1+Math.floor((((seed-1)%n)/7));
  var rec={
    id:PREFIX+String(seed).padStart(6,'0'),
    name:e.t,
    title:DBTITLE+': '+e.t+(cycle>0?' (variant '+cycle+')':''),
    description:SRC==='signature'?('Signature treatment: '+e.sig+' '+e.d):e.d,
    category:e.cat,
    ladder_rank:ladder,
    ladder_tier:ladderTier(ladder),
    how_it_works:e.h,
    key_points:e.k,
    requirements:e.r,
    standards:e.s,
    citations:e.c,
    src:SRC,
    src_detail:SRC_DETAIL,
    seed:seed
  };
  if(SRC==='signature'){rec.signature_treatment=e.sig;}
  rec.demo={program:e.demo};
  if(opts.category&&rec.category!==opts.category){/* category filter honored at query layer */}
  return rec;
}
function escRx(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function validate(r){
  var errs=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+escRx(PREFIX)+'\\d{6}$').test(r.id||''))errs.push('id');
  if(typeof r.title!=='string'||r.title.indexOf(DBTITLE)!==0)errs.push('title');
  if(CATS.indexOf(r.category)<0)errs.push('category');
  if(!(r.ladder_rank>=1&&r.ladder_rank<=5))errs.push('ladder_rank');
  if(['Foundations','Compounded','Advanced'].indexOf(r.ladder_tier)<0)errs.push('ladder_tier');
  if(r.src!==SRC)errs.push('src');
  if(typeof r.description!=='string'||r.description.length<200)errs.push('description');
  REQUIRED.forEach(function(k){if(r[k]===undefined||r[k]===null)errs.push('missing:'+k);});
  if(!Array.isArray(r.key_points)||r.key_points.length<3)errs.push('key_points');
  if(!r.demo||typeof r.demo.program!=='string'||!r.demo.program.length)errs.push('demo');
  return {ok:errs.length===0,errors:errs};
}
function driftCheck(rec,sample){
  var dups=(sample||[]).filter(function(x){return x&&x.title===rec.title&&x.category===rec.category;});
  return dups.length?{ok:false,errors:['duplicate title+category already in archive']}:{ok:true,errors:[]};
}
var api={generate:generate,validate:validate,driftCheck:driftCheck,slug:"ai-toolmaking-project-scaffolding",version:"jahdb-ai-toolmaking-project-scaffolding-1.0"};
if(typeof module!=='undefined'&&module.exports)module.exports=api;
if(typeof window!=='undefined'){
  window["jahdb_ai_toolmaking_project_scaffolding"]=api;
  try{if(window.JAHDB&&JAHDB.registerGenerator)JAHDB.registerGenerator("ai-toolmaking-project-scaffolding",api);}catch(e){}
}
})();
